@@ -0,0 +1,92 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const headers = { "X-Larder-Site": "annex" };
+const annexBatch = (store, itemId = 2, qty = 20) => {
+  const batch = { ...store.data.batches.find((b) => b.itemId === itemId), id: store.nextId("batch"), location: "annex-fridge", qty };
+  store.data.batches.push(batch);
+  return batch;
+};
+
+test("site selection defaults to main, is case insensitive, and rejects unknown sites", async () => {
+  const { handle } = app();
+  assert.deepEqual(await handle({ path: "/items" }), await handle({ path: "/items", headers: { "x-larder-site": "main" } }));
+  const bad = await handle({ path: "/items", headers: { "X-Larder-Site": "missing" } });
+  assert.equal(bad.status, 400);
+  assert.equal(bad.body.error.code, "unknown_site");
+  assert.match(bad.body.error.message, /missing/);
+  assert.equal((await handle({ path: "/items", headers: { "x-LaRdEr-SiTe": "annex" } })).body[0].onHand, 0);
+});
+
+test("batches, on hand, alerts and stock value are isolated while catalogues are shared", async () => {
+  const { handle, store } = app();
+  const batch = annexBatch(store);
+  batch.expires = "2026-10-29";
+  assert.deepEqual((await handle({ path: "/batches", headers })).body, [batch]);
+  assert.deepEqual((await handle({ path: "/batches?itemId=1", headers })).body, []);
+  assert.equal((await handle({ path: `/batches/${batch.id}` })).body.error.code, "unknown_batch");
+  assert.equal((await handle({ path: "/batches/3", headers })).body.error.code, "unknown_batch");
+  const milk = (await handle({ path: "/items/2", headers })).body;
+  assert.equal(milk.onHand, 20);
+  assert.deepEqual(milk.batches, [batch]);
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, 10);
+  const alerts = (await handle({ path: "/alerts", headers })).body;
+  assert.deepEqual(alerts.expiring, [batch]);
+  assert.ok(!alerts.lowStock.some((i) => i.itemId === 2));
+  assert.ok(alerts.lowStock.some((i) => i.itemId === 1));
+  assert.equal((await handle({ path: "/reports/stock-value", headers })).body.totalCents, 2580);
+  for (const path of ["/suppliers", "/dishes", "/recipes/1/cost"]) {
+    assert.deepEqual(await handle({ path, headers }), await handle({ path }));
+  }
+});
+
+test("cooking and waste cannot use another site's stock", async () => {
+  const { handle, store } = app();
+  const milk = annexBatch(store);
+  const before = structuredClone(store.data);
+  const request = { method: "POST", path: "/recipes/2/cook", headers, body: { portions: 10 } };
+  assert.equal((await handle(request)).status, 409);
+  assert.deepEqual(store.data, before);
+  annexBatch(store, 3);
+  annexBatch(store, 4);
+  const mainBefore = structuredClone(store.data.batches.filter((b) => b.location !== "annex-fridge"));
+  assert.equal((await handle(request)).status, 200);
+  assert.equal(milk.qty, 18);
+  assert.deepEqual(store.data.batches.filter((b) => b.location !== "annex-fridge"), mainBefore);
+  const waste = { method: "POST", path: `/batches/${milk.id}/waste`, body: { qty: 1 } };
+  assert.equal((await handle(waste)).status, 404);
+  assert.equal((await handle({ ...waste, headers })).status, 201);
+  assert.equal(milk.qty, 17);
+});
+
+test("stock-takes reject other sites' locations, batches and take ids", async () => {
+  const { handle, store } = app();
+  const batch = annexBatch(store);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers, body: { location: "fridge" } })).body.error.code, "unknown_location");
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers, body: { location: "annex-fridge" } })).body;
+  const counts = { method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: batch.id, counted: 7 } };
+  assert.equal((await handle(counts)).status, 404);
+  assert.equal((await handle({ ...counts, headers, body: { batchId: 3, counted: 7 } })).status, 404);
+  assert.equal((await handle({ ...counts, headers })).status, 200);
+  const finish = { method: "POST", path: `/stocktakes/${take.id}/finish` };
+  assert.equal((await handle(finish)).status, 404);
+  assert.equal(batch.qty, 20);
+  assert.equal((await handle({ ...finish, headers })).status, 200);
+  assert.equal(batch.qty, 7);
+  assert.equal(store.data.movements.at(-1).batchId, batch.id);
+});
+
+test("order receipts only create batches in the request's site", async () => {
+  const { handle, store } = app();
+  const request = { method: "POST", path: "/orders/2/receive", headers, body: { lots: [
+    { lot: "a", location: "annex-fridge" }, { lot: "b", location: "fridge" },
+  ] } };
+  const before = structuredClone(store.data);
+  assert.equal((await handle(request)).body.error.code, "unknown_location");
+  assert.deepEqual(store.data, before);
+  request.body.lots[1].location = "annex-fridge";
+  const received = await handle(request);
+  assert.equal(received.status, 200);
+  assert.ok(received.body.batches.every((b) => b.location === "annex-fridge"));
+});
